    internal sealed class HousekeepingAcquisitionMetrics
    {
        public string Provider { get; set; }
        public long PeopleEvaluated { get; set; }
        public long CacheHits { get; set; }
        public long ProviderCalls { get; set; }
        public long CandidatesExamined { get; set; }
        public long MaximumCandidatesForOnePerson { get; set; }
        public long PeopleOverEightCandidates { get; set; }
        public long DecisiveLinkedMediaStops { get; set; }
        public void FinishPerson(long candidates)
        {
            CandidatesExamined += candidates;
            MaximumCandidatesForOnePerson = Math.Max(MaximumCandidatesForOnePerson, candidates);
            if (candidates > 8) PeopleOverEightCandidates++;
        }
        public void Add(HousekeepingAcquisitionMetrics other)
        {
            if(other==null)return;PeopleEvaluated+=other.PeopleEvaluated;CacheHits+=other.CacheHits;ProviderCalls+=other.ProviderCalls;CandidatesExamined+=other.CandidatesExamined;MaximumCandidatesForOnePerson=Math.Max(MaximumCandidatesForOnePerson,other.MaximumCandidatesForOnePerson);PeopleOverEightCandidates+=other.PeopleOverEightCandidates;DecisiveLinkedMediaStops+=other.DecisiveLinkedMediaStops;
        }
    }

    internal sealed class HousekeepingRepository : IDisposable
    {
        private const int BatchSize = 1000;
        private readonly IDatabaseConnection db;

        public HousekeepingRepository(IApplicationPaths paths)
            : this(ArchiveDatabase.ResolvePath(paths))
        {
        }

        internal HousekeepingRepository(string path)
        {
            ArchiveDatabase.RequireExisting(path);
            db=SQLite3.Open(path,ConnectionFlags.ReadWrite|ConnectionFlags.PrivateCache|ConnectionFlags.NoMutex,null,new Dictionary<string,delegate_collation>(),new Dictionary<Tuple<string,int>,Action<IReadOnlyList<sqlite3_value>,sqlite3_context>>(),true,false);
            db.Execute("PRAGMA foreign_keys=ON"); db.Execute("PRAGMA busy_timeout=5000"); db.Execute("PRAGMA synchronous=NORMAL");
            ArchiveDatabase.ValidateObjects(db,"media-first person truth","housekeeping_run","media_truth_run","media_truth_person","media_truth_identity","media_truth_lineage","media_truth_credit","media_truth_credit_evidence","media_truth_issue","media_truth_change","media_truth_projection","media_truth_latest_projection");
            ArchiveDatabase.ValidateObjects(db,"housekeeping provider evidence","provider_credit_observation","provider_production_evidence","provider_normalization_mismatch","emby_person_media_provider_support","emby_person_media_provider_mismatch");
            ArchiveDatabase.ValidateMigrations(db,11);
        }

        public long Run(DateTime cutoff,CancellationToken token,Action<string,double,TimeSpan> report)
        {
            var clock=Stopwatch.StartNew(); long run=0;
            using(token.Register(()=>{try{db.Interrupt();}catch{}})) try
            {
                Phase(token,report,clock,"Creating media-first truth run",1); run=StartRun(cutoff);
                Phase(token,report,clock,"Reconstructing people from exact media casts",5);
                Tx(x=>{MediaFirstTruthBuilder.Materialize(x,run,(stage,elapsed)=>report?.Invoke("Media-first: "+stage,Math.Min(97,5+elapsed.TotalSeconds/10),clock.Elapsed));State(x,run,"media-first-derived-truth",98);});
                Phase(token,report,clock,"Finalizing automatic and human-review summaries",98);
                Tx(x=>CompleteMediaFirst(x,run));
                token.ThrowIfCancellationRequested(); return run;
            }
            catch(SQLiteException) when(token.IsCancellationRequested){if(run!=0)Stop(run,"cancelled","SQLite interrupted by Emby cancellation");throw new OperationCanceledException("Housekeeping cancelled",token);}
            catch(OperationCanceledException){if(run!=0)Stop(run,"cancelled","Cancelled by Emby");throw;}
            catch(Exception ex){if(run!=0)Stop(run,"failed",ex.ToString());throw;}
        }

        private long StartRun(DateTime cutoff)
        {
            long id=0; var now=Now(); Tx(x=>{
                Exec(x,"UPDATE housekeeping_run SET status='failed',phase='interrupted',heartbeat_utc=@now,completed_utc=@now,error=coalesce(error,'A later media-first rebuild found this run incomplete; its transaction was rolled back.') WHERE status='running'",s=>s.TryBind("@now",now));
                Exec(x,"UPDATE experiment_run SET status='failed',completed_utc=@now WHERE status='running' AND run_id IN(SELECT run_id FROM housekeeping_run WHERE phase='interrupted')",s=>s.TryBind("@now",now));
                x.Execute("INSERT OR IGNORE INTO algorithm(name,version,code_hash,configuration_json) VALUES('person-housekeeping','media-first-v1','media-first-exact-credit-reconstruction','{\"derivedTruth\":true,\"autoCommitScope\":\"derived-truth-only\",\"humanReviewPreservesCurrentRelationship\":true,\"embyPerson\":\"continuity-container\",\"exactMediaFirst\":true,\"conflatedProviderIdentityWithheld\":true}')");
                Exec(x,"INSERT INTO experiment_run(algorithm_id,truth_id,observation_cutoff_utc,mask_policy_json,started_utc,status) SELECT algorithm_id,1,@cutoff,json_object('providerRequests','archive-first-fetch-missing','decisionModel','media-first-exact-credit-reconstruction'),@now,'running' FROM algorithm WHERE name='person-housekeeping' AND version='media-first-v1'",s=>{s.TryBind("@cutoff",cutoff.ToString("o"));s.TryBind("@now",now);}); id=LastId(x);
                Exec(x,"INSERT INTO housekeeping_run(run_id,algorithm_version,base_truth_id,phase,progress,status,observation_cutoff_utc,started_utc,heartbeat_utc) VALUES(@run,'media-first-v1',1,'starting',1,'running',@cutoff,@now,@now)",s=>{s.TryBind("@run",id);s.TryBind("@cutoff",cutoff.ToString("o"));s.TryBind("@now",now);});}); return id;
        }

        private static void CompleteMediaFirst(IDatabaseConnection x,long run)
        {
            var now=Now();
            Exec(x,"UPDATE housekeeping_run SET derived_truth_id=NULL,phase='completed',progress=100,status='completed',heartbeat_utc=@now,completed_utc=@now WHERE run_id=@run",s=>{s.TryBind("@now",now);s.TryBind("@run",run);});
            Exec(x,"UPDATE experiment_run SET status='completed',completed_utc=@now WHERE run_id=@run",s=>{s.TryBind("@now",now);s.TryBind("@run",run);});
        }

        private static void IdentitySignals(IDatabaseConnection x,long run)=>Exec(x,@"INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,candidate_external_id,current_name,candidate_name,score,confidence,evidence_text,created_utc)
SELECT @run,p.emby_id,'emby:'||p.emby_id,'tmdb',CASE r.provenance WHEN 'direct' THEN 'identity-live' WHEN 'direct-unavailable' THEN 'identity-unavailable' ELSE 'identity-unresolved' END,p.tmdb_id,r.resolved_tmdb_id,p.name,e.name,CASE r.provenance WHEN 'direct' THEN 1 WHEN 'direct-unavailable' THEN 0 ELSE .5 END,CASE r.provenance WHEN 'direct' THEN .99 WHEN 'direct-unavailable' THEN .95 ELSE .25 END,'TMDB status: '||r.provenance,@now FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id LEFT JOIN tmdb_entity e ON e.entity_type='person' AND e.tmdb_id=r.resolved_tmdb_id WHERE p.item_type='person'
UNION ALL SELECT @run,p.emby_id,'emby:'||p.emby_id,'tvdb',CASE r.provenance WHEN 'direct' THEN 'identity-live' WHEN 'direct-unavailable' THEN 'identity-unavailable' ELSE 'identity-unresolved' END,p.tvdb_id,r.resolved_tvdb_id,p.name,e.name,CASE r.provenance WHEN 'direct' THEN 1 WHEN 'direct-unavailable' THEN 0 ELSE .5 END,CASE r.provenance WHEN 'direct' THEN .99 WHEN 'direct-unavailable' THEN .95 ELSE .25 END,'TVDB status: '||r.provenance,@now FROM emby_item p JOIN item_resolution r ON r.emby_id=p.emby_id LEFT JOIN tvdb_entity e ON e.entity_type='person' AND e.tvdb_id=r.resolved_tvdb_id WHERE p.item_type='person'",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void MissingIdentitySignals(IDatabaseConnection x,long run)=>Exec(x,@"INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,current_name,score,confidence,evidence_text,created_utc)
SELECT @run,p.emby_id,'emby:'||p.emby_id,'tmdb',CASE WHEN p.tmdb_id IS NULL THEN 'identity-missing' ELSE 'identity-unresolved' END,p.tmdb_id,p.name,0,.2,CASE WHEN p.tmdb_id IS NULL THEN 'No TMDB person ID is assigned' ELSE 'No TMDB resolution observation is archived' END,@now FROM emby_item p LEFT JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.emby_id IS NULL
UNION ALL SELECT @run,p.emby_id,'emby:'||p.emby_id,'tvdb',CASE WHEN p.tvdb_id IS NULL THEN 'identity-missing' ELSE 'identity-unresolved' END,p.tvdb_id,p.name,0,.2,CASE WHEN p.tvdb_id IS NULL THEN 'No TVDB person ID is assigned' ELSE 'No TVDB resolution observation is archived' END,@now FROM emby_item p LEFT JOIN item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.emby_id IS NULL",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void UniversalIdentityAudits(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH media AS (
SELECT p.emby_id person_id,p.name current_name,p.tmdb_id current_id,er.media_emby_id,m.item_type media_type,coalesce(m.tmdb_id,mr.resolved_tmdb_id) production_id,coalesce(json_extract(me.raw_json,'$.show_id'),parent.tmdb_id,pr.resolved_tmdb_id) series_id,me.tmdb_id checked_id,exact.person_tmdb_id exact_person,broad.person_tmdb_id broad_person
FROM emby_item p LEFT JOIN emby_relationship er ON er.person_emby_id=p.emby_id LEFT JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tmdb_entity me ON me.tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND me.entity_type=m.item_type LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN tmdb_item_resolution pr ON pr.emby_id=parent.emby_id LEFT JOIN tmdb_credit exact ON exact.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND exact.production_type=m.item_type AND exact.person_tmdb_id=p.tmdb_id LEFT JOIN tmdb_credit broad ON m.item_type='episode' AND broad.production_tmdb_id=coalesce(json_extract(me.raw_json,'$.show_id'),parent.tmdb_id,pr.resolved_tmdb_id) AND broad.production_type='series' AND broad.person_tmdb_id=p.tmdb_id WHERE p.item_type='person'), classified AS (
SELECT media.*,CASE WHEN media_emby_id IS NULL THEN 'no-media' WHEN production_id IS NULL THEN 'unresolved' WHEN exact_person IS NOT NULL THEN 'exact' WHEN media_type='episode' AND broad_person IS NOT NULL THEN 'broader' WHEN media_type='episode' AND EXISTS(SELECT 1 FROM provider_production_evidence e WHERE e.provider='tmdb' AND e.production_type='episode' AND e.production_provider_id=production_id AND e.component='screen-credits' AND e.acquisition_status='complete' AND e.raw_credit_count=e.normalized_credit_count) THEN 'not-present' WHEN media_type<>'episode' AND checked_id IS NOT NULL THEN 'not-present' ELSE 'unchecked' END result FROM media), audit AS (
SELECT person_id,current_name,current_id,count(DISTINCT media_emby_id) linked,count(DISTINCT CASE WHEN result IN('exact','broader','not-present') THEN media_emby_id END) checked,count(DISTINCT CASE WHEN result='exact' THEN media_emby_id END) exact_count,count(DISTINCT CASE WHEN result='broader' THEN media_emby_id END) broader_count,count(DISTINCT CASE WHEN result='not-present' THEN media_emby_id END) not_present,count(DISTINCT CASE WHEN result IN('unresolved','unchecked') THEN media_emby_id END) unresolved FROM classified GROUP BY person_id,current_name,current_id)
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,current_name,linked_media_count,checked_media_count,supported_media_count,score,confidence,evidence_text,evidence_json,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tmdb',CASE WHEN current_id IS NULL THEN 'identity-audit-missing' WHEN linked=0 THEN 'identity-audit-unlinked' WHEN exact_count+broader_count>0 AND not_present=0 THEN 'identity-supported' WHEN exact_count+broader_count>0 THEN 'identity-partially-supported' WHEN checked=0 THEN 'identity-audit-incomplete' ELSE 'identity-unsupported' END,current_id,current_name,linked,checked,exact_count+broader_count,CASE WHEN linked=0 THEN NULL ELSE (exact_count+.9*broader_count)/linked END,CASE WHEN linked=0 THEN .25 WHEN exact_count+broader_count>0 AND not_present=0 THEN .95 WHEN exact_count+broader_count>0 THEN .65 WHEN checked=linked THEN .2 ELSE .3 END,'TMDB identity audit: linked='||linked||'; checked='||checked||'; exact='||exact_count||'; broader-series='||broader_count||'; not-present='||not_present||'; unresolved='||unresolved,json_object('linked',linked,'checked',checked,'exact_scope',exact_count,'broader_series_scope',broader_count,'not_present',not_present,'unresolved',unresolved),@now FROM audit",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,@"WITH episode_series AS (SELECT DISTINCT production_tvdb_id,source_tvdb_id FROM tvdb_credit_observation WHERE production_type='episode' AND source_entity_type='series'), media AS (
SELECT p.emby_id person_id,p.name current_name,p.tvdb_id current_id,er.media_emby_id,m.item_type media_type,coalesce(m.tvdb_id,mr.resolved_tvdb_id) production_id,coalesce(parent.tvdb_id,pr.resolved_tvdb_id,series_credit.source_tvdb_id) series_id,me.tvdb_id checked_id,exact.person_tvdb_id exact_person,broad.person_tvdb_id broad_person
FROM emby_item p LEFT JOIN emby_relationship er ON er.person_emby_id=p.emby_id LEFT JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tvdb_entity me ON me.tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND me.entity_type=m.item_type LEFT JOIN episode_series series_credit ON m.item_type='episode' AND series_credit.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN item_resolution pr ON pr.emby_id=parent.emby_id LEFT JOIN credit exact ON exact.subject_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND exact.subject_type=m.item_type AND exact.person_tvdb_id=p.tvdb_id LEFT JOIN credit broad ON m.item_type='episode' AND broad.subject_tvdb_id=coalesce(parent.tvdb_id,pr.resolved_tvdb_id,series_credit.source_tvdb_id) AND broad.subject_type='series' AND broad.person_tvdb_id=p.tvdb_id WHERE p.item_type='person'), classified AS (
SELECT media.*,CASE WHEN media_emby_id IS NULL THEN 'no-media' WHEN production_id IS NULL THEN 'unresolved' WHEN exact_person IS NOT NULL THEN 'exact' WHEN media_type='episode' AND broad_person IS NOT NULL THEN 'broader' WHEN media_type='episode' AND EXISTS(SELECT 1 FROM provider_production_evidence e WHERE e.provider='tvdb' AND e.production_type='episode' AND e.production_provider_id=production_id AND e.component='screen-credits' AND e.acquisition_status='complete' AND e.raw_credit_count=e.normalized_credit_count) THEN 'not-present' WHEN media_type<>'episode' AND checked_id IS NOT NULL THEN 'not-present' ELSE 'unchecked' END result FROM media), audit AS (
SELECT person_id,current_name,current_id,count(DISTINCT media_emby_id) linked,count(DISTINCT CASE WHEN result IN('exact','broader','not-present') THEN media_emby_id END) checked,count(DISTINCT CASE WHEN result='exact' THEN media_emby_id END) exact_count,count(DISTINCT CASE WHEN result='broader' THEN media_emby_id END) broader_count,count(DISTINCT CASE WHEN result='not-present' THEN media_emby_id END) not_present,count(DISTINCT CASE WHEN result IN('unresolved','unchecked') THEN media_emby_id END) unresolved FROM classified GROUP BY person_id,current_name,current_id)
