SELECT @run,person_id,'emby:'||person_id,'tvdb',CASE WHEN current_id IS NULL THEN 'identity-audit-missing' WHEN linked=0 THEN 'identity-audit-unlinked' WHEN exact_count+broader_count>0 AND not_present=0 THEN 'identity-supported' WHEN exact_count+broader_count>0 THEN 'identity-partially-supported' WHEN checked=0 THEN 'identity-audit-incomplete' ELSE 'identity-unsupported' END,current_id,current_name,linked,checked,exact_count+broader_count,CASE WHEN linked=0 THEN NULL ELSE (exact_count+.9*broader_count)/linked END,CASE WHEN linked=0 THEN .25 WHEN exact_count+broader_count>0 AND not_present=0 THEN .95 WHEN exact_count+broader_count>0 THEN .65 WHEN checked=linked THEN .2 ELSE .3 END,'TVDB identity audit: linked='||linked||'; checked='||checked||'; exact='||exact_count||'; broader-series='||broader_count||'; not-present='||not_present||'; unresolved='||unresolved,json_object('linked',linked,'checked',checked,'exact_scope',exact_count,'broader_series_scope',broader_count,'not_present',not_present,'unresolved',unresolved),@now FROM audit",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
