            Exec(x,@"WITH candidates AS (SELECT rc.emby_id,rc.tmdb_id candidate_id,rc.name candidate_name FROM tmdb_resolution_candidate rc), media AS (
SELECT p.emby_id person_id,p.name current_name,p.tmdb_id current_id,c.candidate_id,c.candidate_name,er.media_emby_id,m.item_type media_type,coalesce(nullif(er.role,''),er.person_type) relationship_role,coalesce(m.tmdb_id,mr.resolved_tmdb_id) production_id,coalesce(parent.tmdb_id,pr.resolved_tmdb_id,json_extract(me.raw_json,'$.show_id')) series_id,m.name media_name
FROM emby_item p JOIN candidates c ON c.emby_id=p.emby_id JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tmdb_entity me ON me.tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND me.entity_type=m.item_type LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN tmdb_item_resolution pr ON pr.emby_id=parent.emby_id), classified AS (
SELECT media.*,CASE WHEN production_id IS NULL THEN 'media-unavailable' WHEN EXISTS(SELECT 1 FROM tmdb_credit_observation c WHERE c.production_tmdb_id=media.production_id AND c.production_type=media.media_type AND c.person_tmdb_id=media.candidate_id) THEN 'confirmed-exact-scope' WHEN media_type='episode' AND series_id IS NOT NULL AND EXISTS(SELECT 1 FROM tmdb_credit_observation c WHERE c.production_tmdb_id=media.series_id AND c.production_type='series' AND c.person_tmdb_id=media.candidate_id) THEN 'confirmed-broader-series-scope' WHEN media_type='episode' AND EXISTS(SELECT 1 FROM provider_production_evidence e WHERE e.provider='tmdb' AND e.production_type='episode' AND e.production_provider_id=production_id AND e.component='screen-credits' AND e.acquisition_status='complete' AND e.raw_credit_count=e.normalized_credit_count) THEN 'not-present' WHEN media_type<>'episode' AND EXISTS(SELECT 1 FROM tmdb_entity e WHERE e.tmdb_id=media.production_id AND e.entity_type=media.media_type) THEN 'not-present' ELSE 'unchecked' END result,
coalesce((SELECT c.job_or_character FROM tmdb_credit_observation c WHERE c.production_tmdb_id=media.production_id AND c.production_type=media.media_type AND c.person_tmdb_id=media.candidate_id LIMIT 1),(SELECT c.job_or_character FROM tmdb_credit_observation c WHERE media.media_type='episode' AND c.production_tmdb_id=media.series_id AND c.production_type='series' AND c.person_tmdb_id=media.candidate_id LIMIT 1)) provider_role FROM media)
