coalesce((SELECT c.role_name FROM tvdb_credit_observation c WHERE c.production_tvdb_id=media.production_id AND c.production_type=media.media_type AND c.person_tvdb_id=media.candidate_id LIMIT 1),(SELECT c.role_name FROM tvdb_credit_observation c WHERE media.media_type='episode' AND c.production_tvdb_id=media.series_id AND c.production_type='series' AND c.person_tvdb_id=media.candidate_id LIMIT 1)) provider_role FROM media)
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,candidate_external_id,current_name,candidate_name,media_emby_id,media_type,relationship_role,provider_role,linked_media_count,checked_media_count,supported_media_count,score,confidence,evidence_text,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tvdb',result,current_id,candidate_id,current_name,candidate_name,media_emby_id,media_type,relationship_role,provider_role,1,CASE WHEN result IN('confirmed-exact-scope','confirmed-broader-series-scope','not-present') THEN 1 ELSE 0 END,CASE WHEN result LIKE 'confirmed-%' THEN 1 ELSE 0 END,CASE result WHEN 'confirmed-exact-scope' THEN 1 WHEN 'confirmed-broader-series-scope' THEN .9 WHEN 'not-present' THEN 0 ELSE NULL END,CASE result WHEN 'confirmed-exact-scope' THEN .95 WHEN 'confirmed-broader-series-scope' THEN .85 WHEN 'not-present' THEN .8 ELSE .2 END,'TVDB candidate '||candidate_id||' '||coalesce(candidate_name,'')||' on Emby media '||media_emby_id||' '||coalesce(media_name,'')||': '||result||'; Emby role='||coalesce(relationship_role,'-')||'; provider role='||coalesce(provider_role,'-'),@now FROM classified",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
