 (p.tmdb_id IS NOT NULL AND (EXISTS(SELECT 1 FROM tmdb_entity e WHERE e.entity_type='person' AND e.tmdb_id=p.tmdb_id AND lower(e.name)=lower(p.name)) OR EXISTS(SELECT 1 FROM tmdb_alias a WHERE a.entity_type='person' AND a.tmdb_id=p.tmdb_id AND lower(a.alias)=lower(p.name))) AND EXISTS(SELECT 1 FROM emby_relationship er JOIN emby_item m ON m.emby_id=er.media_emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=m.tmdb_id AND c.person_tmdb_id=p.tmdb_id WHERE er.person_emby_id=p.emby_id))
