SELECT @run,p.emby_id,'emby:'||p.emby_id,'update',CASE WHEN EXISTS(SELECT 1 FROM emby_item d WHERE d.item_type='person' AND d.emby_id<>p.emby_id AND lower(d.name)=lower(v.tmdb_name)) THEN 'review-existing-emby-person' ELSE 'rename-person' END,CASE WHEN EXISTS(SELECT 1 FROM emby_item d WHERE d.item_type='person' AND d.emby_id<>p.emby_id AND lower(d.name)=lower(v.tmdb_name)) THEN 'emby-name-collision' ELSE 'media-backed-provider-rename' END,'tmdb',p.name,v.tmdb_name,
(SELECT count(*) FROM emby_relationship e WHERE e.person_emby_id=p.emby_id),(SELECT count(*) FROM emby_relationship e JOIN emby_item m ON m.emby_id=e.media_emby_id WHERE e.person_emby_id=p.emby_id AND m.tmdb_id IS NOT NULL),(SELECT count(DISTINCT e.media_emby_id) FROM emby_relationship e JOIN emby_item m ON m.emby_id=e.media_emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=m.tmdb_id AND c.person_tmdb_id=p.tmdb_id WHERE e.person_emby_id=p.emby_id),CASE WHEN EXISTS(SELECT 1 FROM emby_item d WHERE d.item_type='person' AND d.emby_id<>p.emby_id AND lower(d.name)=lower(v.tmdb_name)) THEN .65 ELSE .90 END,'Current name is not confirmed by any healthy media-backed provider identity; TMDB proposed name is backed by linked credits',@now
FROM emby_item p JOIN provider_identity_signals v ON v.emby_id=p.emby_id WHERE p.item_type='person' AND NOT EXISTS(SELECT 1 FROM anchored_name a WHERE a.emby_id=p.emby_id) AND v.tmdb_provenance='direct' AND v.resolved_tmdb_id=p.tmdb_id AND v.tmdb_name IS NOT NULL AND lower(v.tmdb_name)<>lower(p.name) AND EXISTS(SELECT 1 FROM emby_relationship er JOIN emby_item m ON m.emby_id=er.media_emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=m.tmdb_id AND c.person_tmdb_id=p.tmdb_id WHERE er.person_emby_id=p.emby_id)
