(SELECT count(*) FROM emby_relationship e WHERE e.person_emby_id=p.emby_id),(SELECT count(*) FROM emby_relationship e JOIN emby_item m ON m.emby_id=e.media_emby_id WHERE e.person_emby_id=p.emby_id AND m.tvdb_id IS NOT NULL),(SELECT count(DISTINCT e.media_emby_id) FROM emby_relationship e JOIN emby_item m ON m.emby_id=e.media_emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=m.tvdb_id AND c.person_tvdb_id=p.tvdb_id WHERE e.person_emby_id=p.emby_id),CASE WHEN EXISTS(SELECT 1 FROM emby_item d WHERE d.item_type='person' AND d.emby_id<>p.emby_id AND lower(d.name)=lower(v.tvdb_name)) THEN .60 ELSE .86 END,'Current name is not confirmed by any healthy media-backed provider identity; TVDB proposed name is backed by linked credits',@now
FROM emby_item p JOIN provider_identity_signals v ON v.emby_id=p.emby_id WHERE p.item_type='person' AND NOT EXISTS(SELECT 1 FROM anchored_name a WHERE a.emby_id=p.emby_id) AND v.tvdb_provenance='direct' AND v.resolved_tvdb_id=p.tvdb_id AND v.tvdb_name IS NOT NULL AND lower(v.tvdb_name)<>lower(p.name) AND EXISTS(SELECT 1 FROM emby_relationship er JOIN emby_item m ON m.emby_id=er.media_emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=m.tvdb_id AND c.person_tvdb_id=p.tvdb_id WHERE er.person_emby_id=p.emby_id)",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void Merges(IDatabaseConnection x,long run)=>Exec(x,@"WITH identities AS (
SELECT 'tmdb' provider,tmdb_id external_id,emby_id FROM emby_item WHERE item_type='person' AND tmdb_id IS NOT NULL
UNION ALL SELECT 'tvdb',tvdb_id,emby_id FROM emby_item WHERE item_type='person' AND tvdb_id IS NOT NULL), duplicates AS (
SELECT provider,external_id FROM identities GROUP BY provider,external_id HAVING count(*)>1),
support AS (
SELECT i.provider,i.external_id,i.emby_id,
 (SELECT count(*) FROM emby_relationship er WHERE er.person_emby_id=i.emby_id) linked,
 (SELECT count(DISTINCT er.media_emby_id) FROM emby_relationship er JOIN emby_item m ON m.emby_id=er.media_emby_id
  WHERE er.person_emby_id=i.emby_id AND ((i.provider='tmdb' AND EXISTS(SELECT 1 FROM tmdb_credit_observation tc WHERE tc.production_tmdb_id=m.tmdb_id AND tc.person_tmdb_id=i.external_id))
   OR (i.provider='tvdb' AND EXISTS(SELECT 1 FROM tvdb_credit_observation vc WHERE vc.production_tvdb_id=m.tvdb_id AND vc.person_tvdb_id=i.external_id)))) supported
FROM identities i JOIN duplicates d ON d.provider=i.provider AND d.external_id=i.external_id), candidates AS (
SELECT provider,external_id,min(emby_id) survivor,group_concat(emby_id) participants,sum(linked) linked,sum(supported) supported,count(*) people,
 sum(CASE WHEN supported>0 THEN 1 ELSE 0 END) supported_people FROM support GROUP BY provider,external_id HAVING count(*)>1)
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,survivor,'emby:'||survivor,'merge','review-merge','shared-provider-identity',provider,participants,external_id,linked,linked,supported,.85,
'Shared '||upper(provider)||' ID '||external_id||' is provider-credit-backed for all '||people||' Emby people; choose and lock a survivor only after reviewing identities and every linked credit',@now
FROM candidates WHERE supported_people=people",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void SplitsV2(IDatabaseConnection x,long run)=>Exec(x,@"WITH candidate_media AS (
SELECT person_emby_id,provider,current_external_id,candidate_external_id,media_emby_id FROM housekeeping_signal WHERE run_id=@run AND signal_type IN('confirmed-exact-scope','confirmed-broader-series-scope') AND candidate_external_id IS NOT NULL), candidate_people AS (
SELECT DISTINCT person_emby_id,provider FROM candidate_media), current_media AS (
SELECT p.emby_id person_emby_id,'tmdb' provider,p.tmdb_id current_id,er.media_emby_id FROM candidate_people q JOIN emby_item p ON p.emby_id=q.person_emby_id AND q.provider='tmdb' JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND c.production_type=m.item_type AND c.person_tmdb_id=p.tmdb_id
UNION ALL SELECT p.emby_id,'tvdb',p.tvdb_id,er.media_emby_id FROM candidate_people q JOIN emby_item p ON p.emby_id=q.person_emby_id AND q.provider='tvdb' JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND c.production_type=m.item_type AND c.person_tvdb_id=p.tvdb_id), candidate_stats AS (
SELECT person_emby_id,provider,current_external_id current_id,candidate_external_id candidate_id,count(DISTINCT media_emby_id) candidate_media FROM candidate_media WHERE candidate_external_id<>coalesce(current_external_id,'') GROUP BY person_emby_id,provider,current_external_id,candidate_external_id), current_stats AS (
SELECT person_emby_id,provider,current_id,count(DISTINCT media_emby_id) current_media FROM current_media GROUP BY person_emby_id,provider,current_id), shared_stats AS (
SELECT c.person_emby_id,c.provider,c.candidate_external_id candidate_id,count(DISTINCT c.media_emby_id) shared_media FROM candidate_media c JOIN current_media m ON m.person_emby_id=c.person_emby_id AND m.provider=c.provider AND m.media_emby_id=c.media_emby_id WHERE c.candidate_external_id<>coalesce(c.current_external_id,'') GROUP BY c.person_emby_id,c.provider,c.candidate_external_id), partitions AS (
SELECT c.person_emby_id,c.provider,c.current_id,c.candidate_id,c.candidate_media,m.current_media,coalesce(s.shared_media,0) shared_media FROM candidate_stats c JOIN current_stats m ON m.person_emby_id=c.person_emby_id AND m.provider=c.provider LEFT JOIN shared_stats s ON s.person_emby_id=c.person_emby_id AND s.provider=c.provider AND s.candidate_id=c.candidate_id WHERE c.candidate_media>0 AND m.current_media>0 AND coalesce(s.shared_media,0)=0), grouped AS (
SELECT person_emby_id,provider,current_id,group_concat(candidate_id) ids,sum(candidate_media) candidate_media,max(current_media) current_media FROM partitions GROUP BY person_emby_id,provider,current_id)
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,g.person_emby_id,'emby:'||g.person_emby_id,'split','review-split','linked-media-partition',g.provider,g.current_id,g.ids,(SELECT count(DISTINCT media_emby_id) FROM emby_relationship er WHERE er.person_emby_id=g.person_emby_id),g.current_media+g.candidate_media,g.current_media+g.candidate_media,.88,'Emby person '||g.person_emby_id||' has disjoint linked-media support for current '||upper(g.provider)||' ID '||coalesce(g.current_id,'-')||' and candidate ID(s) '||g.ids||'; review relationship partition and existing Emby ownership before creating a person',@now FROM grouped g
WHERE NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=g.person_emby_id AND h.recommendation_type='review-split' AND h.provider=g.provider)",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void Splits(IDatabaseConnection x,long run)=>Exec(x,@"WITH s AS (SELECT p.emby_id,'tmdb' provider,p.tmdb_id current_id,cp.tmdb_id candidate,count(DISTINCT er.media_emby_id) media FROM emby_item p JOIN emby_item cp ON cp.item_type='person' AND cp.emby_id<>p.emby_id AND cp.name=p.name AND cp.tmdb_id IS NOT NULL JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=m.tmdb_id AND c.person_tmdb_id=cp.tmdb_id WHERE p.item_type='person' GROUP BY p.emby_id,p.tmdb_id,cp.tmdb_id UNION ALL SELECT p.emby_id,'tvdb',p.tvdb_id,cp.tvdb_id,count(DISTINCT er.media_emby_id) FROM emby_item p JOIN emby_item cp ON cp.item_type='person' AND cp.emby_id<>p.emby_id AND cp.name=p.name AND cp.tvdb_id IS NOT NULL JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=m.tvdb_id AND c.person_tvdb_id=cp.tvdb_id WHERE p.item_type='person' GROUP BY p.emby_id,p.tvdb_id,cp.tvdb_id),q AS(SELECT emby_id,provider,current_id,count(*) n,sum(media) media,group_concat(candidate) ids FROM s GROUP BY emby_id,provider,current_id HAVING count(*)>1) INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,supported_media_count,confidence,evidence_summary,created_utc) SELECT @run,emby_id,'emby:'||emby_id,'split','review-split','linked-media-partition',provider,current_id,ids,media,.75,'Emby person '||emby_id||' has linked credits partitioned across multiple name-compatible '||upper(provider)||' identities; review each media relationship before creating or moving people',@now FROM q",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void CrossProviderSplits(IDatabaseConnection x,long run)=>Exec(x,@"WITH identities AS (
SELECT p.emby_id,p.name,p.tmdb_id,p.tvdb_id,p.imdb_id,te.name tmdb_name,json_extract(te.raw_json,'$.external_ids.imdb_id') tmdb_imdb,rt.remote_id tvdb_tmdb,ri.remote_id tvdb_imdb,(SELECT s.candidate_external_id FROM housekeeping_signal s JOIN remote_id ct ON ct.entity_type='person' AND ct.tvdb_id=s.candidate_external_id AND ct.source_name='TheMovieDB.com' AND ct.remote_id=p.tmdb_id JOIN remote_id ci ON ci.entity_type='person' AND ci.tvdb_id=s.candidate_external_id AND ci.source_name='IMDB' AND ci.remote_id=coalesce(p.imdb_id,json_extract(te.raw_json,'$.external_ids.imdb_id')) WHERE s.run_id=@run AND s.person_emby_id=p.emby_id AND s.provider='tvdb' AND s.signal_type LIKE 'confirmed-%' GROUP BY s.candidate_external_id ORDER BY count(DISTINCT s.media_emby_id) DESC LIMIT 1) retain_tvdb
FROM emby_item p JOIN tmdb_entity te ON te.entity_type='person' AND te.tmdb_id=p.tmdb_id JOIN tvdb_entity ve ON ve.entity_type='person' AND ve.tvdb_id=p.tvdb_id JOIN remote_id rt ON rt.entity_type='person' AND rt.tvdb_id=p.tvdb_id AND rt.source_name='TheMovieDB.com' AND rt.remote_id<>p.tmdb_id JOIN remote_id ri ON ri.entity_type='person' AND ri.tvdb_id=p.tvdb_id AND ri.source_name='IMDB' AND ri.remote_id<>coalesce(p.imdb_id,json_extract(te.raw_json,'$.external_ids.imdb_id')) WHERE p.item_type='person' AND p.tmdb_id IS NOT NULL AND p.tvdb_id IS NOT NULL), tmdb_supported AS (
SELECT DISTINCT i.emby_id,er.media_emby_id FROM identities i JOIN emby_relationship er ON er.person_emby_id=i.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND c.production_type=m.item_type AND c.person_tmdb_id=i.tmdb_id), tvdb_supported AS (
SELECT DISTINCT i.emby_id,er.media_emby_id FROM identities i JOIN emby_relationship er ON er.person_emby_id=i.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND c.production_type=m.item_type AND c.person_tvdb_id=i.tvdb_id), tmdb_stats AS (
SELECT emby_id,count(*) media FROM tmdb_supported GROUP BY emby_id), tvdb_stats AS (
SELECT emby_id,count(*) media FROM tvdb_supported GROUP BY emby_id), shared_stats AS (
SELECT t.emby_id,count(*) media FROM tmdb_supported t JOIN tvdb_supported v ON v.emby_id=t.emby_id AND v.media_emby_id=t.media_emby_id GROUP BY t.emby_id), linked_stats AS (
SELECT i.emby_id,count(DISTINCT er.media_emby_id) media FROM identities i JOIN emby_relationship er ON er.person_emby_id=i.emby_id GROUP BY i.emby_id), support AS (
SELECT i.*,coalesce(t.media,0) tmdb_media,coalesce(v.media,0) tvdb_media,coalesce(s.media,0) shared_media,coalesce(l.media,0) linked,(SELECT group_concat(m.name,', ') FROM tmdb_supported z JOIN emby_item m ON m.emby_id=z.media_emby_id WHERE z.emby_id=i.emby_id) tmdb_titles,(SELECT group_concat(m.name,', ') FROM tvdb_supported z JOIN emby_item m ON m.emby_id=z.media_emby_id WHERE z.emby_id=i.emby_id) tvdb_titles FROM identities i LEFT JOIN tmdb_stats t ON t.emby_id=i.emby_id LEFT JOIN tvdb_stats v ON v.emby_id=i.emby_id LEFT JOIN shared_stats s ON s.emby_id=i.emby_id LEFT JOIN linked_stats l ON l.emby_id=i.emby_id), eligible AS (
SELECT * FROM support WHERE tvdb_tmdb IS NOT NULL AND tvdb_tmdb<>tmdb_id AND tvdb_imdb IS NOT NULL AND coalesce(imdb_id,tmdb_imdb,'')<>'' AND tvdb_imdb<>coalesce(imdb_id,tmdb_imdb) AND tmdb_media>0 AND tvdb_media>0 AND shared_media=0)
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,emby_id,'emby:'||emby_id,'split','review-split','cross-provider-media-partition','cross-provider','TMDB='||tmdb_id||'; TVDB='||tvdb_id||'; IMDb='||coalesce(imdb_id,tmdb_imdb,'-'),json_object('retain_tmdb',tmdb_id,'retain_tvdb',retain_tvdb,'retain_imdb',coalesce(imdb_id,tmdb_imdb),'split_tmdb',tvdb_tmdb,'split_tvdb',tvdb_id,'split_imdb',tvdb_imdb),linked,tmdb_media+tvdb_media,tmdb_media+tvdb_media,.97,
'Actionable identity/media partition for Emby '||emby_id||' '||name||'. Retain cluster: TMDB '||tmdb_id||' / TVDB '||coalesce(retain_tvdb,'-')||' / IMDb '||coalesce(imdb_id,tmdb_imdb,'-')||' on ['||coalesce(tmdb_titles,'')||']. Create a new Emby person and move ['||coalesce(tvdb_titles,'')||'] to split cluster: TMDB '||tvdb_tmdb||' / TVDB '||tvdb_id||' / IMDb '||tvdb_imdb||'. Provider-native supported media are disjoint; shared supported media='||shared_media||'. The reviewer chooses the survivor if library context requires a different disposition.',@now FROM eligible
WHERE NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=eligible.emby_id AND h.recommendation_type='review-split' AND h.primary_signal_type='cross-provider-media-partition')",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void GraphOperationDecisions(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH replacements AS (
SELECT r.recommendation_id,r.person_emby_id source_id,r.provider,r.current_value,r.proposed_value,r.linked_media_count,r.checked_media_count,r.supported_media_count,r.confidence,p.name source_name
FROM housekeeping_recommendation r JOIN emby_item p ON p.emby_id=r.person_emby_id
WHERE r.run_id=@run AND r.recommendation_type='replace-provider-id'), candidate_keys AS (
SELECT recommendation_id,provider key_type,proposed_value key_value FROM replacements
UNION SELECT r.recommendation_id,CASE x.source_name WHEN 'imdb' THEN 'imdb' WHEN 'tvdb' THEN 'tvdb' WHEN 'wikidata' THEN 'wikidata' END,x.external_id FROM replacements r JOIN tmdb_external_id x ON r.provider='tmdb' AND x.entity_type='person' AND x.tmdb_id=r.proposed_value WHERE x.source_name IN('imdb','tvdb','wikidata')
UNION SELECT r.recommendation_id,CASE WHEN x.source_name='IMDB' THEN 'imdb' WHEN x.source_name='TheMovieDB.com' THEN 'tmdb' WHEN lower(x.source_name)='wikidata' THEN 'wikidata' END,x.remote_id FROM replacements r JOIN remote_id x ON r.provider='tvdb' AND x.entity_type='person' AND x.tvdb_id=r.proposed_value WHERE x.source_name IN('IMDB','TheMovieDB.com') OR lower(x.source_name)='wikidata'
UNION SELECT r.recommendation_id,'tmdb',t.tmdb_id FROM replacements r JOIN remote_id i ON r.provider='tvdb' AND i.entity_type='person' AND i.tvdb_id=r.proposed_value AND i.source_name='IMDB' JOIN tmdb_external_id t ON t.entity_type='person' AND t.source_name='imdb' AND t.external_id=i.remote_id
UNION SELECT r.recommendation_id,'tmdb',t.tmdb_id FROM replacements r JOIN remote_id w ON r.provider='tvdb' AND w.entity_type='person' AND w.tvdb_id=r.proposed_value AND lower(w.source_name)='wikidata' JOIN tmdb_external_id t ON t.entity_type='person' AND t.source_name='wikidata' AND t.external_id=w.remote_id
UNION SELECT r.recommendation_id,'tvdb',v.tvdb_id FROM replacements r JOIN tmdb_external_id i ON r.provider='tmdb' AND i.entity_type='person' AND i.tmdb_id=r.proposed_value AND i.source_name='imdb' JOIN remote_id v ON v.entity_type='person' AND v.source_name='IMDB' AND v.remote_id=i.external_id
UNION SELECT r.recommendation_id,'tvdb',v.tvdb_id FROM replacements r JOIN tmdb_external_id w ON r.provider='tmdb' AND w.entity_type='person' AND w.tmdb_id=r.proposed_value AND w.source_name='wikidata' JOIN remote_id v ON v.entity_type='person' AND lower(v.source_name)='wikidata' AND v.remote_id=w.external_id), clusters AS (
SELECT r.*,max(CASE WHEN k.key_type='tmdb' THEN k.key_value END) tmdb_id,max(CASE WHEN k.key_type='tvdb' THEN k.key_value END) tvdb_id,max(CASE WHEN k.key_type='imdb' THEN k.key_value END) imdb_id,max(CASE WHEN k.key_type='wikidata' THEN k.key_value END) wikidata_id
FROM replacements r JOIN candidate_keys k ON k.recommendation_id=r.recommendation_id GROUP BY r.recommendation_id), owner_keys AS (
SELECT emby_id,'tmdb' key_type,tmdb_id key_value FROM emby_item WHERE item_type='person' AND tmdb_id IS NOT NULL
UNION SELECT emby_id,'tvdb',tvdb_id FROM emby_item WHERE item_type='person' AND tvdb_id IS NOT NULL
UNION SELECT emby_id,'imdb',imdb_id FROM emby_item WHERE item_type='person' AND imdb_id IS NOT NULL
UNION SELECT p.emby_id,CASE x.source_name WHEN 'imdb' THEN 'imdb' WHEN 'tvdb' THEN 'tvdb' WHEN 'wikidata' THEN 'wikidata' END,x.external_id FROM emby_item p JOIN tmdb_external_id x ON x.entity_type='person' AND x.tmdb_id=p.tmdb_id WHERE p.item_type='person' AND x.source_name IN('imdb','tvdb','wikidata')
UNION SELECT p.emby_id,CASE WHEN x.source_name='IMDB' THEN 'imdb' WHEN x.source_name='TheMovieDB.com' THEN 'tmdb' WHEN lower(x.source_name)='wikidata' THEN 'wikidata' END,x.remote_id FROM emby_item p JOIN remote_id x ON x.entity_type='person' AND x.tvdb_id=p.tvdb_id WHERE p.item_type='person' AND (x.source_name IN('IMDB','TheMovieDB.com') OR lower(x.source_name)='wikidata')), owner_matches AS (
SELECT DISTINCT c.recommendation_id,c.source_id,o.emby_id owner_id FROM clusters c JOIN candidate_keys k ON k.recommendation_id=c.recommendation_id JOIN owner_keys o ON o.key_type=k.key_type AND o.key_value=k.key_value AND o.emby_id<>c.source_id), unique_owner AS (
SELECT recommendation_id,min(owner_id) owner_id FROM owner_matches GROUP BY recommendation_id HAVING count(DISTINCT owner_id)=1), chosen AS (
SELECT c.*,u.owner_id,o.name owner_name,o.tmdb_id owner_tmdb,o.tvdb_id owner_tvdb,coalesce(o.imdb_id,tx.external_id,vi.remote_id) owner_imdb,
 coalesce((SELECT group_concat('media '||s.media_emby_id||' '||coalesce(e.name,'')||' ['||coalesce(s.relationship_role,'')||coalesce(': '||s.provider_role,'')||']',' | ') FROM housekeeping_signal s LEFT JOIN emby_item e ON e.emby_id=s.media_emby_id WHERE s.run_id=@run AND s.person_emby_id=c.source_id AND s.provider=c.provider AND s.candidate_external_id=c.proposed_value AND s.signal_type LIKE 'confirmed-%'),
 (SELECT group_concat('media '||m.emby_id||' '||coalesce(m.name,'')||' ['||coalesce(er.person_type,'')||coalesce(': '||er.role,'')||']',' | ') FROM emby_relationship er JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution tr ON tr.emby_id=m.emby_id LEFT JOIN item_resolution vr ON vr.emby_id=m.emby_id WHERE er.person_emby_id=c.source_id AND ((c.provider='tmdb' AND EXISTS(SELECT 1 FROM tmdb_credit_observation tc WHERE tc.production_tmdb_id=coalesce(m.tmdb_id,tr.resolved_tmdb_id) AND tc.production_type=m.item_type AND tc.person_tmdb_id=c.proposed_value)) OR (c.provider='tvdb' AND EXISTS(SELECT 1 FROM tvdb_credit_observation vc WHERE vc.production_tvdb_id=coalesce(m.tvdb_id,vr.resolved_tvdb_id) AND vc.production_type=m.item_type AND vc.person_tvdb_id=c.proposed_value))))) relationship_moves
FROM clusters c JOIN unique_owner u ON u.recommendation_id=c.recommendation_id JOIN emby_item o ON o.emby_id=u.owner_id LEFT JOIN tmdb_external_id tx ON tx.entity_type='person' AND tx.tmdb_id=o.tmdb_id AND tx.source_name='imdb' LEFT JOIN remote_id vi ON vi.entity_type='person' AND vi.tvdb_id=o.tvdb_id AND vi.source_name='IMDB')
UPDATE housekeeping_recommendation SET
 person_emby_id=(SELECT min(source_id,owner_id) FROM chosen WHERE recommendation_id=housekeeping_recommendation.recommendation_id),
 subject_truth_entity_id='emby:'||(SELECT min(source_id,owner_id) FROM chosen WHERE recommendation_id=housekeeping_recommendation.recommendation_id),
 operation='merge',recommendation_type='review-merge',primary_signal_type='supported-identity-owned-by-emby',
 current_value=(SELECT CASE WHEN source_id<owner_id THEN source_id||','||owner_id ELSE owner_id||','||source_id END FROM chosen WHERE recommendation_id=housekeeping_recommendation.recommendation_id),
 confidence=(SELECT min(.98,.78+.15*supported_media_count/max(1,linked_media_count)+CASE WHEN imdb_id IS NOT NULL OR wikidata_id IS NOT NULL THEN .04 ELSE 0 END) FROM chosen WHERE recommendation_id=housekeeping_recommendation.recommendation_id),
 evidence_summary=coalesce((SELECT 'Move supported relationship(s) from Emby '||source_id||' '||coalesce(source_name,'(name unavailable)')||' to existing Emby '||owner_id||' '||coalesce(owner_name,'(name unavailable)')||'. Candidate identity cluster: TMDB '||coalesce(tmdb_id,'-')||' / TVDB '||coalesce(tvdb_id,'-')||' / IMDb '||coalesce(imdb_id,'-')||' / Wikidata '||coalesce(wikidata_id,'-')||'. Existing owner identities: TMDB '||coalesce(owner_tmdb,'-')||' / TVDB '||coalesce(owner_tvdb,'-')||' / IMDb '||coalesce(owner_imdb,'-')||'. Provider-native support='||coalesce(supported_media_count,0)||'/'||coalesce(linked_media_count,0)||'. Proposed relationship moves: ['||coalesce(relationship_moves,'supporting media titles unavailable')||']. The anchor is an immutable investigation root, not the guaranteed survivor; do not transmute it when the supported identity already has an Emby owner.' FROM chosen WHERE recommendation_id=housekeeping_recommendation.recommendation_id),evidence_summary)
WHERE recommendation_id IN(SELECT recommendation_id FROM chosen)",s=>s.TryBind("@run",run));
        }

        private static void ConsolidateReviewCases(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH details AS (
SELECT r.recommendation_id,p.name current_name,e.name candidate_name,
 (SELECT group_concat(a.alias,', ') FROM tvdb_alias a WHERE a.entity_type='person' AND a.tvdb_id=r.proposed_value) aliases,
 (SELECT group_concat(i.source_name||'='||i.remote_id,', ') FROM remote_id i WHERE i.entity_type='person' AND i.tvdb_id=r.proposed_value AND i.source_name IN('IMDB','TheMovieDB.com','Wikidata')) external_ids,
 coalesce((SELECT ce.evidence FROM candidate_evidence ce WHERE ce.emby_id=r.person_emby_id AND ce.tvdb_id=r.proposed_value),'provider-native linked-media candidate') candidate_reason
FROM housekeeping_recommendation r JOIN emby_item p ON p.emby_id=r.person_emby_id JOIN tvdb_entity e ON e.entity_type='person' AND e.tvdb_id=r.proposed_value
WHERE r.run_id=@run AND r.provider='tvdb' AND r.recommendation_type='replace-provider-id')
UPDATE housekeeping_recommendation SET evidence_summary=coalesce((SELECT 'Set TVDB identity from '||coalesce(current_value,'(none)')||' to '||coalesce(proposed_value,'(none)')||' for Emby '||person_emby_id||' '||coalesce(current_name,'(name unavailable)')||'. TVDB canonical name='||coalesce(candidate_name,'(name unavailable)')||'; aliases=['||coalesce(aliases,'')||']; external identities=['||coalesce(external_ids,'')||']. Provider-native linked-media support='||coalesce(supported_media_count,0)||'/'||coalesce(linked_media_count,0)||'. Candidate route: '||coalesce(candidate_reason,'provider-native linked-media candidate')||'. Retain the Emby person and relationships; review the canonical rename and identity hydration as part of this single repair case.' FROM details WHERE recommendation_id=housekeeping_recommendation.recommendation_id),evidence_summary) WHERE recommendation_id IN(SELECT recommendation_id FROM details)",s=>s.TryBind("@run",run));
            Exec(x,@"WITH collision_merge AS (
