        private static void CrossProviderFilmographyReplacements(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH candidates AS (
SELECT r.recommendation_id,r.person_emby_id,r.current_value current_tvdb,ce.tvdb_id candidate_tvdb,p.name,p.tmdb_id,
       coalesce(p.imdb_id,ti.external_id) imdb_id,
       count(DISTINCT CASE WHEN tc.person_tmdb_id IS NOT NULL THEN cp.production_type||':'||cp.production_tvdb_id END) mapped_overlap,
       (SELECT count(*) FROM candidate_tvdb_production a WHERE a.emby_id=ce.emby_id AND a.candidate_tvdb_id=ce.tvdb_id AND a.production_type IN('series','movie')) candidate_productions,
       (SELECT count(*) FROM emby_person_media_provider_support s WHERE s.person_emby_id=p.emby_id AND s.provider='tmdb' AND s.evidence_state LIKE 'supported-%') anchor_support,
       (SELECT count(*) FROM emby_relationship er WHERE er.person_emby_id=p.emby_id) linked
FROM housekeeping_recommendation r JOIN emby_item p ON p.emby_id=r.person_emby_id
JOIN candidate_evidence ce ON ce.emby_id=p.emby_id AND ce.entity_type='person'
LEFT JOIN tmdb_external_id ti ON ti.entity_type='person' AND ti.tmdb_id=p.tmdb_id AND ti.source_name='imdb'
JOIN remote_id pt ON pt.entity_type='person' AND pt.tvdb_id=ce.tvdb_id AND pt.source_name='TheMovieDB.com' AND pt.remote_id=p.tmdb_id
JOIN remote_id pi ON pi.entity_type='person' AND pi.tvdb_id=ce.tvdb_id AND pi.source_name='IMDB' AND pi.remote_id=coalesce(p.imdb_id,ti.external_id)
LEFT JOIN candidate_tvdb_production cp ON cp.emby_id=ce.emby_id AND cp.candidate_tvdb_id=ce.tvdb_id AND cp.production_type IN('series','movie')
LEFT JOIN remote_id px ON px.entity_type=cp.production_type AND px.tvdb_id=cp.production_tvdb_id AND px.source_name='TheMovieDB.com'
LEFT JOIN tmdb_credit tc ON tc.person_tmdb_id=p.tmdb_id AND tc.production_type=cp.production_type AND tc.production_tmdb_id=px.remote_id
WHERE r.run_id=@run AND r.recommendation_type='remove-provider-id' AND r.provider='tvdb' AND ce.tvdb_id<>coalesce(p.tvdb_id,'')
GROUP BY r.recommendation_id,ce.tvdb_id HAVING anchor_support>0 AND mapped_overlap>=2), ranked AS (
SELECT c.*,dense_rank() OVER(PARTITION BY recommendation_id ORDER BY mapped_overlap DESC) choice_rank,
       count(*) OVER(PARTITION BY recommendation_id,mapped_overlap) tied FROM candidates c), chosen AS (
SELECT * FROM ranked WHERE choice_rank=1 AND tied=1)
UPDATE housekeeping_recommendation SET operation='change_identity',recommendation_type='replace-provider-id',primary_signal_type='cross-provider-identity-filmography',proposed_value=(SELECT candidate_tvdb FROM chosen WHERE chosen.recommendation_id=housekeeping_recommendation.recommendation_id),confidence=.96,acceptance_path='cross-provider-identity-and-filmography',identity_confidence=.99,relationship_confidence=.95,operation_confidence=.96,evidence_summary=coalesce((SELECT 'Replace unavailable TVDB '||current_tvdb||' with TVDB '||candidate_tvdb||' for Emby '||person_emby_id||' '||name||'. The candidate directly links to TMDB '||tmdb_id||' and IMDb '||imdb_id||'; the healthy TMDB identity supports '||anchor_support||'/'||linked||' linked Emby media. Exact production-ID crosswalks confirm '||mapped_overlap||' shared off-library series. TVDB support on the linked Emby media remains separately absent or unresolved.' FROM chosen WHERE chosen.recommendation_id=housekeeping_recommendation.recommendation_id),evidence_summary) WHERE recommendation_id IN(SELECT recommendation_id FROM chosen)",s=>s.TryBind("@run",run));
            Exec(x,@"WITH candidates AS (
SELECT r.recommendation_id,r.person_emby_id,r.current_value current_tmdb,rc.tmdb_id candidate_tmdb,p.name,p.tvdb_id,
       coalesce(p.imdb_id,vi.remote_id) imdb_id,
       count(DISTINCT CASE WHEN vc.person_provider_id IS NOT NULL THEN tc.production_type||':'||tc.production_tmdb_id END) mapped_overlap,
       (SELECT count(*) FROM tmdb_credit a WHERE a.person_tmdb_id=rc.tmdb_id AND a.production_type IN('series','movie')) candidate_productions,
       (SELECT count(*) FROM emby_person_media_provider_support s WHERE s.person_emby_id=p.emby_id AND s.provider='tvdb' AND s.evidence_state LIKE 'supported-%') anchor_support,
       (SELECT count(*) FROM emby_relationship er WHERE er.person_emby_id=p.emby_id) linked
FROM housekeeping_recommendation r JOIN emby_item p ON p.emby_id=r.person_emby_id
JOIN tmdb_resolution_candidate rc ON rc.emby_id=p.emby_id AND rc.entity_type='person'
LEFT JOIN remote_id vi ON vi.entity_type='person' AND vi.tvdb_id=p.tvdb_id AND vi.source_name='IMDB'
JOIN tmdb_external_id ct ON ct.entity_type='person' AND ct.tmdb_id=rc.tmdb_id AND ct.source_name='tvdb' AND ct.external_id=p.tvdb_id
JOIN tmdb_external_id ci ON ci.entity_type='person' AND ci.tmdb_id=rc.tmdb_id AND ci.source_name='imdb' AND ci.external_id=coalesce(p.imdb_id,vi.remote_id)
LEFT JOIN tmdb_credit tc ON tc.person_tmdb_id=rc.tmdb_id AND tc.production_type IN('series','movie')
LEFT JOIN tmdb_external_id px ON px.entity_type=tc.production_type AND px.tmdb_id=tc.production_tmdb_id AND px.source_name='tvdb'
LEFT JOIN provider_credit_observation vc ON vc.provider='tvdb' AND vc.person_provider_id=p.tvdb_id AND vc.production_type=tc.production_type AND vc.production_provider_id=px.external_id
WHERE r.run_id=@run AND r.recommendation_type='remove-provider-id' AND r.provider='tmdb' AND rc.tmdb_id<>coalesce(p.tmdb_id,'')
GROUP BY r.recommendation_id,rc.tmdb_id HAVING anchor_support>0 AND mapped_overlap>=2), ranked AS (
SELECT c.*,dense_rank() OVER(PARTITION BY recommendation_id ORDER BY mapped_overlap DESC) choice_rank,count(*) OVER(PARTITION BY recommendation_id,mapped_overlap) tied FROM candidates c), chosen AS (SELECT * FROM ranked WHERE choice_rank=1 AND tied=1)
UPDATE housekeeping_recommendation SET operation='change_identity',recommendation_type='replace-provider-id',primary_signal_type='cross-provider-identity-filmography',proposed_value=(SELECT candidate_tmdb FROM chosen WHERE chosen.recommendation_id=housekeeping_recommendation.recommendation_id),confidence=.96,acceptance_path='cross-provider-identity-and-filmography',identity_confidence=.99,relationship_confidence=.95,operation_confidence=.96,evidence_summary=coalesce((SELECT 'Replace unavailable TMDB '||current_tmdb||' with TMDB '||candidate_tmdb||' for Emby '||person_emby_id||' '||name||'. The candidate directly links to TVDB '||tvdb_id||' and IMDb '||imdb_id||'; the healthy TVDB identity supports '||anchor_support||'/'||linked||' linked Emby media. Exact production-ID crosswalks confirm '||mapped_overlap||' shared off-library series. TMDB support on the linked Emby media remains separately absent or unresolved.' FROM chosen WHERE chosen.recommendation_id=housekeeping_recommendation.recommendation_id),evidence_summary) WHERE recommendation_id IN(SELECT recommendation_id FROM chosen)",s=>s.TryBind("@run",run));
        }

        private static void MaterializeRecommendationActions(IDatabaseConnection x,long run)
        {
            Exec(x,"DELETE FROM housekeeping_recommendation_action WHERE run_id=@run",s=>s.TryBind("@run",run));
            Exec(x,@"WITH matches AS (
SELECT ren.recommendation_id rename_id,ren.person_emby_id,ren.current_value,ren.proposed_value,ren.confidence,ren.evidence_summary,
       parent.recommendation_id parent_id,parent.recommendation_type,
       row_number() OVER(PARTITION BY ren.recommendation_id ORDER BY CASE parent.recommendation_type WHEN 'review-split' THEN 1 ELSE 2 END,parent.confidence DESC,parent.recommendation_id) choice
FROM housekeeping_recommendation ren JOIN housekeeping_recommendation parent ON parent.run_id=ren.run_id AND parent.recommendation_type IN('review-merge','review-split')
 AND (parent.person_emby_id=ren.person_emby_id OR (','||coalesce(parent.current_value,'')||',') LIKE '%,'||ren.person_emby_id||',%')
WHERE ren.run_id=@run AND ren.recommendation_type='rename-person')
INSERT INTO housekeeping_recommendation_action(run_id,recommendation_id,action_order,action_type,source_emby_id,current_value,proposed_value,dependency,operator_choice_required,confidence,summary,created_utc)
SELECT @run,parent_id,60,'rename-person',person_emby_id,current_value,proposed_value,
       CASE recommendation_type WHEN 'review-merge' THEN 'after-survivor-selection' ELSE 'after-relationship-partition' END,
       CASE recommendation_type WHEN 'review-merge' THEN 1 ELSE 0 END,confidence,
       'Dependent name action for Emby '||person_emby_id||': '||current_value||' -> '||proposed_value||'. '||evidence_summary,@now
FROM matches WHERE choice=1",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,@"DELETE FROM housekeeping_recommendation AS ren WHERE ren.run_id=@run AND ren.recommendation_type='rename-person' AND EXISTS(
SELECT 1 FROM housekeeping_recommendation parent WHERE parent.run_id=ren.run_id AND parent.recommendation_type IN('review-merge','review-split')
AND (parent.person_emby_id=ren.person_emby_id OR (','||coalesce(parent.current_value,'')||',') LIKE '%,'||ren.person_emby_id||',%'))",s=>s.TryBind("@run",run));

            Exec(x,@"INSERT INTO housekeeping_recommendation_action(run_id,recommendation_id,action_order,action_type,source_emby_id,current_value,proposed_value,dependency,operator_choice_required,confidence,summary,created_utc)
SELECT @run,recommendation_id,10,
 CASE recommendation_type WHEN 'review-merge' THEN 'select-survivor' WHEN 'review-split' THEN 'retain-person' WHEN 'replace-provider-id' THEN 'set-provider-id' WHEN 'remove-provider-id' THEN 'remove-provider-id' WHEN 'rename-person' THEN 'rename-person' WHEN 'review-unresolved-provider-id' THEN 'review-identity' ELSE 'review-relationship' END,
 person_emby_id,current_value,proposed_value,NULL,CASE WHEN recommendation_type IN('review-merge','review-split','review-unresolved-provider-id') THEN 1 ELSE 0 END,coalesce(operation_confidence,confidence),
 CASE recommendation_type WHEN 'review-merge' THEN 'Choose the surviving Emby person from participants ['||coalesce(current_value,'')||'].' WHEN 'review-split' THEN 'Confirm the identity clusters and which relationships remain on Emby '||person_emby_id||'.' WHEN 'replace-provider-id' THEN 'Set '||upper(coalesce(provider,''))||' identity from '||coalesce(current_value,'(none)')||' to '||coalesce(proposed_value,'(none)')||'.' WHEN 'remove-provider-id' THEN 'Remove '||upper(coalesce(provider,''))||' identity '||coalesce(current_value,'(none)')||'.' WHEN 'rename-person' THEN 'Rename Emby '||person_emby_id||' from '||coalesce(current_value,'')||' to '||coalesce(proposed_value,'')||'.' ELSE evidence_summary END,@now
FROM housekeeping_recommendation WHERE run_id=@run",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,@"INSERT INTO housekeeping_recommendation_action(run_id,recommendation_id,action_order,action_type,source_emby_id,dependency,operator_choice_required,confidence,summary,created_utc)
SELECT @run,recommendation_id,30,'move-relationships',person_emby_id,'after-survivor-selection',1,coalesce(relationship_confidence,confidence),'Move only the relationships assigned by the displayed provider/media support matrix to the selected survivor.',@now FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='review-merge'
UNION ALL SELECT @run,recommendation_id,40,'retire-empty-person',person_emby_id,'after-relationship-moves',1,coalesce(operation_confidence,confidence),'Retire a losing Emby person only if no relationships remain after the approved moves.',@now FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='review-merge'
UNION ALL SELECT @run,recommendation_id,50,'set-provider-id',person_emby_id,'after-survivor-selection',1,coalesce(identity_confidence,confidence),'Apply the displayed justified '||upper(coalesce(provider,'provider'))||' identity landscape to the selected survivor; preserve unresolved provider locks for operator choice.',@now FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='review-merge'
UNION ALL SELECT @run,recommendation_id,20,'create-person',person_emby_id,'after-identity-partition',1,coalesce(identity_confidence,confidence),'Create a new Emby person only for a supported identity cluster that has no existing owner.',@now FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='review-split'
UNION ALL SELECT @run,recommendation_id,30,'move-relationships',person_emby_id,'after-person-creation-or-owner-selection',1,coalesce(relationship_confidence,confidence),'Move each relationship according to the displayed identity-cluster/media partition.',@now FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='review-split'",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
        }

