UNION ALL
SELECT @run,r.recommendation_id,'person-identity','positive','external-person-id','tmdb',r.proposed_value,'imdb',i.external_id,'imdb',i.external_id,.99,'TMDB '||r.proposed_value||' directly identifies IMDb '||i.external_id,11
